optimization-iteration.patch:
diff --git a/scripts/bot-evaluation/host-evidence.ts b/scripts/bot-evaluation/host-evidence.ts
index afc381fa..88f3d22c 100644
--- a/scripts/bot-evaluation/host-evidence.ts
+++ b/scripts/bot-evaluation/host-evidence.ts
@@ -10,6 +10,14 @@ export type RecordValue =
 export interface RecordObject {
   [key: string]: RecordValue;
 }
+const fieldNames = new Map<string, string>();
+function fieldName(key: string): string {
+  const known = fieldNames.get(key);
+  if (known !== undefined) return known;
+  const converted = key.replace(/[A-Z]/g, (c) => "_" + c.toLowerCase());
+  if (fieldNames.size < 32) fieldNames.set(key, converted);
+  return converted;
+}
 export function record(value: unknown): RecordValue {
   if (value === undefined || value === null) return null;
   if (typeof value === "bigint") return value.toString();
@@ -22,7 +30,7 @@ export function record(value: unknown): RecordValue {
   if (Array.isArray(value)) return { item: value.map(record) };
   return Object.fromEntries(
     Object.entries(value as object).map(([k, v]) => [
-      k.replace(/[A-Z]/g, (c) => "_" + c.toLowerCase()),
+      fieldName(k),
       k === "code" ? String(v) : record(v),
     ]),
   );
